using System;
using System.IO;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace DoomSNESed {
    public sealed partial class ConverterForm {
        async Task RunRetail(bool analysis){try{Bin.Require(File.Exists(romPath.Text),"Choose the base SNES ROM.");string output=null;if(!analysis)using(var dialog=new SaveFileDialog{Filter="SNES ROM and native asset patch|*.sfc",FileName="DoomSNESconv-modded.sfc"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;output=dialog.FileName;ProtectInputFiles(output);}string source=romPath.Text;bool expanded=allowExpanded.Checked;Enabled=false;StopAudio();ShowReport();report.Text="Building assets; preserving the selected base ROM levels and episode progression...";StorageSummary summary=null;report.Text=await Task.Run(()=>RetailExport.Build(source,output,resources,graphicChanges,audioChanges,b=>summary=b,textChanges,expanded));storageMeter.Summary=summary;storageMeter.Invalidate();if(!analysis){campaign=Path.ChangeExtension(output,".dse");play.Enabled=File.Exists(campaign)&&!RomLayout.SourceBuilt(new Rom(source,resources).Bytes);}}catch(Exception ex){report.Text="ROM asset build stopped: "+ex.Message;storageMeter.Summary=new StorageSummary{Error=ex.Message};storageMeter.Invalidate();ShowReport();}finally{Enabled=true;}}
    }
    public static partial class RetailExport {
        public static string Build(string source,string output,string resources,System.Collections.Generic.List<GraphicReplacement> graphics,AudioProject audio,Action<StorageSummary> budget,System.Collections.Generic.List<TextReplacement> texts=null,bool allowExpanded=false){var rom=new Rom(source,resources);bool sourceLayout=RomLayout.SourceBuilt(rom.Bytes);bool upgraded=NativeMusicGate.NeedsUpgrade(rom.Bytes);rom.Project.RetailAssets=true;rom.Project.CompactAssets=true;rom.Project.AllowExpandedAssets=allowExpanded;rom.Project.Texts=texts??new System.Collections.Generic.List<TextReplacement>();rom.Project.Graphics=graphics??new System.Collections.Generic.List<GraphicReplacement>();rom.Project.Audio=audio??new AudioProject();byte[] image=rom.Compile();if(budget!=null)budget(rom.Budget);string text="Original-ROM asset build: all base-ROM maps and episode progression preserved.\r\n"+(image.Length==0x200000?"Compatible 2 MiB ROM; ":"Expanded 4 MiB ROM - requires an emulator with expanded Super FX support; Snes9x 1.60 is incompatible. ")+"Staged graphics/audio/text: "+(rom.Budget.Graphics+rom.Budget.Music+rom.Budget.Sounds)+" bytes. "+(image.Length==0x200000?"Reusable space after packing: "+rom.Budget.ReusableFree+" bytes.":"Expanded allocation available: "+rom.Budget.Capacity+" bytes.")+"\r\n"+AudioCli.Report(rom)+(upgraded?"\r\nLegacy music note-stop driver repaired. Existing music and samples preserved; no MIDI reconversion required.\r\n":"");if(output==null)return "ANALYSIS PASSED\r\n"+text;Bin.Require(Path.GetExtension(output).Equals(".sfc",StringComparison.OrdinalIgnoreCase),"Choose an .sfc output filename.");foreach(string file in new[]{output,Path.ChangeExtension(output,".dse"),Path.ChangeExtension(output,".sned"),Path.ChangeExtension(output,".conversion.txt")})Bin.Require(!Path.GetFullPath(file).Equals(Path.GetFullPath(source),StringComparison.OrdinalIgnoreCase),"The base ROM cannot be overwritten.");rom.SaveProject(Path.ChangeExtension(output,".sned"));if(!sourceLayout)rom.SavePatch(Path.ChangeExtension(output,".dse"),image);Bin.Atomic(output,image);text+="\r\nROM: "+output+(sourceLayout?"\r\nDoomFX source layout: emulator/hardware ROM export. This relocated engine is not supported by the native recompiler; no native campaign patch was generated.\r\n":"\r\nNative recomp: use this exact base ROM: "+source+" with "+Path.ChangeExtension(output,".dse")+"\r\n");Bin.Atomic(Path.ChangeExtension(output,".conversion.txt"),System.Text.Encoding.UTF8.GetBytes(text));return text;}
    }
}

